            $localcfg = (array)$CFG;

            foreach ($configs as $config) {

                if (!isset($localcfg[$config->name])) {

                    $localcfg[$config->name] = $config->value;

                } else {

                    if ($localcfg[$config->name] != $config->value ) { 

