function parse_search_field() {
        // We need to change to PARAM_RAW, otherwise PARAM_NOTAGS
        // will drop any input starting with "<" as it thinks it is a tag.
        // Probably not very clean as users might insert dirty html
       // but there's no risk since no harm can be made.
        // return optional_param('f_'.$this->field->id, '', PARAM_NOTAGS);
        return optional_param('f_'.$this->field->id, '', PARAM_RAW);
    }


 function generate_sql($tablealias, $value) {
       // We add the first-char checking, and if it is "greater than" or "lower than"
       // we will generate the sql accordingly
        $firstchar=substr($value,0,1);
        if($firstchar=='>' || $firstchar=='<') {
          return (" ({$tablealias}.fieldid = {$this->field->id} AND {$tablealias}.content $value) ");
       } else {
          return " ({$tablealias}.fieldid = {$this->field->id} AND {$tablealias}.content = '$value') ";
       }
