                $msg->TAG     = $TAG;
                $msg->weekday = $date['weekday'];
                $msg->mday    = $date['mday'];
                $msg->month   = $date['month'];
                $msg->year    = $date['year'];
                fwrite ($restorelog, get_string("backupdatenew", "moodle", $msg));

