Here there my code for Moodle 1.8: I use $errormsg parameter passed by reference for authenticate_user_login function in moodlelib.php. Although I looked at HEAD cvs that you introduced also an $errorcode param in login/index.php. I suppose you can use $errorcode instead of $errormsg for Moodle 1.9 and 2.0 with the same patch:

/******* in moodlelib.php ***********/

function authenticate_user_login($username, $password, &$errormsg = '') {

    global $CFG;

    $authsenabled = get_enabled_auth_plugins();

    if ($user = get_complete_user_data('username', $username)) {
        $auth = empty($user->auth) ? 'manual' : $user->auth;  // use manual if auth not set

        if ($auth=='nologin' or !is_enabled_auth($auth)) {
            add_to_log(0, 'login', 'error', 'index.php', $username);
            error_log('[client '.$_SERVER['REMOTE_ADDR']."]  $CFG->wwwroot  Disabled Login:  $username  ".$_SERVER['HTTP_USER_AGENT']);
            $errormsg = get_string ("disabledlogin");
            return false;
        }
        if (!empty($user->deleted)) {
            add_to_log(0, 'login', 'error', 'index.php', $username);
            error_log('[client '.$_SERVER['REMOTE_ADDR']."]  $CFG->wwwroot  Deleted Login:  $username  ".$_SERVER['HTTP_USER_AGENT']);
            $errormsg = get_string ("deletedlogin");
            return false;
        }
