if you read thus far, here is the patch...

at the end of "course/lib.php" add the following function:

/**
 * Update the number of visible sections in the course and refresh course's view.
 * (does not delete sections from db, nor create new ones!!!)
 *
 * @param object $courseid  - course's id
 * @param object $numsections  - number of visible sections
 */
function set_numsections($courseid,$numsections) {
  global $CFG;

  begin_sql();
  if (!(    set_field("course", "numsections", $numsections, "id", $courseid)
	  && set_field("course", "timemodified", time(), "id", $courseid)
      )) {
      notify("Could not update numsections for course!".$courseid);
  }
  commit_sql();

  redirect($CFG->wwwroot."/course/view.php?id=$courseid");

}


